input.script:
const select = document.getElementById('searchDropdownBox');
select.value = 'search-alias=warehouse-deals';
select.dispatchEvent(new Event('change', { bubbles: true }));
// Now submit the form
const form = select.closest('form');
if (form) {
  // Modify the search keyword
  const input = form.querySelector('input[name="field-keywords"]');
  if (input) input.value = 'nintendo switch lite console';
  form.submit();
}
return { selectedValue: select.value, formSubmitted: !!form };

// Close the AOD overlay
const closeBtn = document.getElementById('aod-close');
if (closeBtn) {
  closeBtn.click();
  return 'Closed';
}
// Or press Escape
document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
return 'Sent Escape';

// Try to close the AOD overlay
const closeBtn = document.querySelector('[aria-label="Close"]');
if (closeBtn) {
  closeBtn.click();
}
// Also try the close button by ID
const aodClose = document.getElementById('aod-close');
if (aodClose) {
  aodClose.click();
}
// Click on the aod-background
const aodBg = document.getElementById('aod-background');
if (aodBg) {
  aodBg.click();
}
return 'Attempted to close AOD';
